#!/usr/bin/env bash
# install-mrmodel-skill.sh — 一行命令安装 mr-model skill (零依赖, 零额外操作)
#
# 用户/agent 跑这一行就完事:
#   主 (jsdelivr 镜像, 绕 raw.githubusercontent.com 5min 边缘缓存):
#     curl -sL https://cdn.jsdelivr.net/gh/Cesario-Lzc/M-Model@main/scripts/install-mrmodel-skill.sh | bash
#   备 (raw, 偶尔 5min 缓存, 新版推上去可能滞后):
#     curl -sL https://raw.githubusercontent.com/Cesario-Lzc/M-Model/main/scripts/install-mrmodel-skill.sh | bash
#
# 行为:
#   1. 宿主探测: env MRMODEL_SKILL_DIR > ~/.claude > ~/.workbuddy > 默认 ~/.claude/skills/mr-model
#   2. 拉取 SKILL.md + manifest.json: CDN 直拉为主 (jsdelivr 主 / raw 备, 与远端实时一致)
#      → 失败 fallback 内嵌 base64 (零外部依赖, 随脚本打包可能非最新)
#   3. 提示输 token (或读 env MR_MCP_TOKEN / 已有 ~/.config/mrmodel/token)
#   4. healthz 探活 (0 配额)
#   5. tools/list 鉴权验证 (11 tool 全可见 = 通)
#
# 高级用法 (本地升级/定制时):
#   MRMODEL_SKILL_SRC_DIR=~/.claude/skills/mr-model bash install-mrmodel-skill.sh
#     → 用指定目录的 SKILL.md (不读内嵌 base64, 用于本地升级)
#   bash install-mrmodel-skill.sh /path/to/SKILL.md /path/to/manifest.json
#     → 外部传入源 (兼容老调用)
#
# 边界:
#   - 0 烧 MCP 配额 (healthz + tools/list 是 McpAuthMiddleware 白名单)
#   - 0 改任何 git 仓 (本机直装)
#   - 0 写主仓 db (token 是业务数据)
#   - 跨设备通用 (mac/linux bash)

set -euo pipefail

# ===== 颜色 =====
RED='\033[0;31m'; GRN='\033[0;32m'; YLW='\033[1;33m'; NC='\033[0m'
info()  { echo -e "${GRN}[✓]${NC} $*"; }
warn()  { echo -e "${YLW}[!]${NC} $*"; }
err()   { echo -e "${RED}[✗]${NC} $*" >&2; }

# ===== 路径 (v1.2.0 宿主探测) =====
# env MRMODEL_SKILL_DIR 最高优先 → 探测 ~/.claude / ~/.workbuddy → 默认 Claude Code
detect_skill_dir() {
    if [ -d "$HOME/.claude" ]; then
        echo "$HOME/.claude/skills/mr-model"
    elif [ -d "$HOME/.workbuddy" ]; then
        echo "$HOME/.workbuddy/skills/mr-model"
    else
        echo "$HOME/.claude/skills/mr-model"
    fi
}
TARGET_SKILL_DIR="${MRMODEL_SKILL_DIR:-$(detect_skill_dir)}"
TARGET_TOKEN_FILE="${MRMODEL_TOKEN_FILE:-$HOME/.config/mrmodel/token}"
MCP_URL="${MRMODEL_MCP_URL:-https://mcp.cesario.top}"

echo "=================================================="
echo "  mr-model skill 一键安装 (一行命令版)"
echo "=================================================="
echo "目标: $TARGET_SKILL_DIR"
echo "MCP:  $MCP_URL"
echo ""

# ===== Step 1: 目录 =====
info "Step 1/4 建目录"
mkdir -p "$TARGET_SKILL_DIR"
mkdir -p "$(dirname "$TARGET_TOKEN_FILE")"
chmod 700 "$(dirname "$TARGET_TOKEN_FILE")"
info "  $TARGET_SKILL_DIR"
info "  $(dirname "$TARGET_TOKEN_FILE") (700)"

# ===== Step 2: 写入 SKILL.md + manifest.json =====
info "Step 2/4 写入 skill 文件"

# 源优先级: env 目录 > 外部参数 > CDN 直拉 > 内嵌 base64
if [ -n "${MRMODEL_SKILL_SRC_DIR:-}" ] && [ -f "$MRMODEL_SKILL_SRC_DIR/SKILL.md" ]; then
    warn "  源: env 目录 $MRMODEL_SKILL_SRC_DIR (本地升级模式)"
    install -m 644 "$MRMODEL_SKILL_SRC_DIR/SKILL.md" "$TARGET_SKILL_DIR/SKILL.md"
    if [ -f "$MRMODEL_SKILL_SRC_DIR/manifest.json" ]; then
        install -m 644 "$MRMODEL_SKILL_SRC_DIR/manifest.json" "$TARGET_SKILL_DIR/manifest.json"
    fi
elif [ -n "${1:-}" ] && [ -f "$1" ]; then
    warn "  源: 外部参数 $1"
    install -m 644 "$1" "$TARGET_SKILL_DIR/SKILL.md"
    [ -n "${2:-}" ] && [ -f "$2" ] && install -m 644 "$2" "$TARGET_SKILL_DIR/manifest.json"
else
    # v1.2.0: CDN 直拉为主 (jsdelivr 主 / raw 备, 与远端实时一致, 永不"忘重渲染装到旧版")
    CDN_BASE="${MRMODEL_CDN_BASE:-https://cdn.jsdelivr.net/gh/Cesario-Lzc/M-Model@main}"
    RAW_BASE="${MRMODEL_RAW_BASE:-https://raw.githubusercontent.com/Cesario-Lzc/M-Model/main}"
    CDN_OK=0
    for BASE in "$CDN_BASE" "$RAW_BASE"; do
        if curl -fsSL --max-time 15 "$BASE/SKILL.md" -o /tmp/mrmodel_skill_md.tmp 2>/dev/null \
           && head -c 10 /tmp/mrmodel_skill_md.tmp | grep -q '^---' \
           && curl -fsSL --max-time 15 "$BASE/manifest.json" -o /tmp/mrmodel_manifest.tmp 2>/dev/null \
           && head -c 1 /tmp/mrmodel_manifest.tmp | grep -q '{'; then
            # v1.2.0: sha 一致性校验 (防 jsdelivr @main 多文件缓存撕裂 — SKILL.md 已刷新 manifest 未刷会装出坏组合)
            GOT_SHA=$(shasum -a 256 /tmp/mrmodel_skill_md.tmp 2>/dev/null | awk '{print $1}' || sha256sum /tmp/mrmodel_skill_md.tmp | awk '{print $1}')
            WANT_SHA=$(grep -o '[a-f0-9]\{64\}' /tmp/mrmodel_manifest.tmp | head -1)
            if [ -n "$GOT_SHA" ] && [ "$GOT_SHA" = "$WANT_SHA" ]; then
                install -m 644 /tmp/mrmodel_skill_md.tmp "$TARGET_SKILL_DIR/SKILL.md"
                install -m 644 /tmp/mrmodel_manifest.tmp "$TARGET_SKILL_DIR/manifest.json"
                CDN_OK=1
                break
            else
                warn "  $BASE 缓存撕裂 (sha ${GOT_SHA:0:8} != manifest ${WANT_SHA:0:8}), 换下一源/fallback"
            fi
        fi
    done
    rm -f /tmp/mrmodel_skill_md.tmp /tmp/mrmodel_manifest.tmp
    if [ "$CDN_OK" = "1" ]; then
        info "  源: CDN 直拉 (jsdelivr 主 / raw 备) — 与远端实时一致"
    else
        warn "  CDN 直拉失败, fallback 内嵌 base64 (随脚本打包, 可能非最新)"
        echo '' | base64 -d > "$TARGET_SKILL_DIR/SKILL.md"
        echo '' | base64 -d > "$TARGET_SKILL_DIR/manifest.json"
    fi
    chmod 644 "$TARGET_SKILL_DIR/SKILL.md" "$TARGET_SKILL_DIR/manifest.json"
fi

SKILL_SHA=$(shasum -a 256 "$TARGET_SKILL_DIR/SKILL.md" 2>/dev/null | awk '{print $1}' || sha256sum "$TARGET_SKILL_DIR/SKILL.md" | awk '{print $1}')
info "  SKILL.md sha256: ${SKILL_SHA:0:16}..."
info "  manifest.json 已写入 (自更新元数据)"

# ===== Step 3: token =====
info "Step 3/4 配置 token"

if [ -n "${MR_MCP_TOKEN:-}" ]; then
    TOKEN="$MR_MCP_TOKEN"
    info "  来源: env MR_MCP_TOKEN (${#TOKEN} 字符)"
elif [ -f "$TARGET_TOKEN_FILE" ]; then
    warn "  已存在 token 文件, 跳过 (如需重设先 rm $TARGET_TOKEN_FILE)"
    TOKEN=$(cat "$TARGET_TOKEN_FILE")
else
    echo ""
    echo "  请输入 mcp token (格式: mcp_live_<48hex> = 57 字符):"
    echo "  生成: 主仓 https://mrmodel.cesario.top/mcp-tokens 页"
    echo "  提示: 任意已生效的 MCP token 都行, 多设备可共用同一个"
    echo ""
    read -r -p "  token: " TOKEN
    [ -z "$TOKEN" ] && { err "token 必填, 退出"; exit 1; }
    if ! echo "$TOKEN" | grep -qE '^mcp_live_[0-9a-f]{48}$'; then
        warn "  token 格式不标准 (期望: mcp_live_<48hex>), 仍写入"
    fi
fi

echo -n "$TOKEN" > "$TARGET_TOKEN_FILE"
chmod 600 "$TARGET_TOKEN_FILE"
info "  token 写入 $TARGET_TOKEN_FILE (600)"

# ===== Step 4: 探活 + 鉴权 =====
info "Step 4/4 验证 MCP 端点 + 鉴权"
HTTP_CODE=$(curl -sS -o /tmp/healthz.json -w "%{http_code}" "$MCP_URL/healthz" --max-time 10 || echo "000")
if [ "$HTTP_CODE" = "200" ]; then
    DB_OK=$(python3 -c "import json; print(json.load(open('/tmp/healthz.json')).get('db_ok','?'))" 2>/dev/null || echo "?")
    info "  healthz: 200 db_ok=$DB_OK"
else
    err "  healthz 返 $HTTP_CODE, MCP 端不可达"
    err "  (脚本已装文件, token 已配, MCP 通了就能用)"
fi

# tools/list 鉴权
RESP=$(curl -sS -X POST "$MCP_URL/mcp" \
    -H "Authorization: Bearer $TOKEN" \
    -H "Content-Type: application/json" \
    -H "Accept: application/json, text/event-stream" \
    -d '{"jsonrpc":"2.0","id":1,"method":"tools/list"}' \
    --max-time 10 || echo "CURL_FAILED")

if echo "$RESP" | grep -q '"name":"query_video_list"'; then
    TOOL_COUNT=$(echo "$RESP" | grep -oE '"name":"[a-z_]+"' | wc -l | tr -d ' ')
    info "  鉴权通过, $TOOL_COUNT tool 全可见"
else
    err "  鉴权失败, 响应:"
    echo "$RESP" | head -c 500
    echo ""
    warn "  请检查: ① token 是否有效 ② 主仓 mcp_tokens 页 status=active ③ 配额是否打爆"
fi

echo ""
echo "=================================================="
echo "  ✅ 装好了！打开 Claude Code 试 '模型先生, 最近有什么视频?'"
echo "=================================================="
echo ""
echo "卸载: rm -rf $TARGET_SKILL_DIR $TARGET_TOKEN_FILE  # 当前宿主: $TARGET_SKILL_DIR"
echo "升级: 重跑本行命令 (覆盖 SKILL.md, 自动 sha256 校验)"
